import React, { useEffect, useRef, useState } from 'react';
import { Quote, ChevronLeft, ChevronRight, Star } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const Testimonials = () => {
  const sectionRef = useRef(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAutoPlaying, setIsAutoPlaying] = useState(true);
  const { testimonials } = useAuth();

  const defaultTestimonials = [
    {
      name: 'Maria Santos',
      role: 'CEO, TechStart Philippines',
      content: 'Project MUN delivered an exceptional e-commerce platform that exceeded our expectations. Their attention to detail and technical expertise made the entire process smooth and professional.',
      rating: 5,
      image: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=100&h=100&fit=crop'
    },
    {
      name: 'John Reyes',
      role: 'Marketing Director, InnovateCorp',
      content: 'Working with the Project MUN team was a game-changer for our business. They transformed our outdated website into a modern, responsive platform that has significantly improved our online presence.',
      rating: 5,
      image: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&h=100&fit=crop'
    },
    {
      name: 'Sarah Chen',
      role: 'Founder, EduLearn Platform',
      content: 'The learning management system they built for us is incredible. User-friendly interface, robust features, and seamless performance. Highly recommend their services!',
      rating: 5,
      image: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop'
    },
    {
      name: 'David Lim',
      role: 'Operations Manager, FoodHub PH',
      content: 'Our restaurant booking system has streamlined our operations tremendously. The team was responsive, creative, and delivered on time. Great collaboration!',
      rating: 5,
      image: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&h=100&fit=crop'
    }
  ];

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );

    const reveals = sectionRef.current?.querySelectorAll('.reveal');
    reveals?.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!isAutoPlaying || testimonials.length === 0) return;

    const timer = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % testimonials.length);
    }, 5000);

    return () => clearInterval(timer);
  }, [isAutoPlaying, testimonials]);

  const nextSlide = () => {
    setIsAutoPlaying(false);
    setCurrentIndex((prev) => (prev + 1) % testimonials.length);
  };

  const prevSlide = () => {
    setIsAutoPlaying(false);
    setCurrentIndex((prev) => (prev - 1 + testimonials.length) % testimonials.length);
  };

  return (
    <section id="testimonials" ref={sectionRef} className="py-24 bg-[#0a1628] relative overflow-hidden">
      {/* Background elements */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-blue-500/5 rounded-full blur-3xl"></div>
      <div className="absolute top-0 right-0 text-[400px] font-serif text-white/[0.02] leading-none select-none">"</div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        {/* Section Header */}
        <div className="text-center mb-16 reveal">
          <span className="inline-block px-4 py-2 rounded-full bg-blue-500/10 text-blue-400 text-sm font-medium mb-4">
            Testimonials
          </span>
          <h2 className="text-4xl sm:text-5xl font-bold text-white mb-6">
            What Our <span className="gradient-text">Clients Say</span>
          </h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            We take pride in delivering exceptional results that our clients love.
          </p>
        </div>

        {/* Testimonials Carousel */}
        <div className="reveal max-w-4xl mx-auto">
          <div className="relative">
            {/* Main Card */}
            <div className="card-minimal rounded-3xl p-8 md:p-12 relative overflow-hidden">
              {/* Quote Icon */}
              <div className="absolute top-8 right-8 w-16 h-16 rounded-full bg-blue-500/10 flex items-center justify-center">
                <Quote className="w-8 h-8 text-blue-400" />
              </div>

              {/* Content */}
              <div className="relative z-10">
                {/* Rating */}
                <div className="flex gap-1 mb-6">
                  {[...Array(testimonials.length > 0 ? testimonials[currentIndex].rating : defaultTestimonials[currentIndex].rating)].map((_, i) => (
                    <Star key={i} className="w-5 h-5 text-yellow-400 fill-yellow-400" />
                  ))}
                </div>

                {/* Quote Text */}
                <p className="text-xl md:text-2xl text-gray-300 leading-relaxed mb-8 italic">
                  "{testimonials.length > 0 ? testimonials[currentIndex].content : defaultTestimonials[currentIndex].content}"
                </p>

                {/* Author */}
                <div className="flex items-center gap-4">
                  <div className="w-14 h-14 rounded-full overflow-hidden ring-2 ring-blue-500/30">
                    <img 
                      src={testimonials.length > 0 ? testimonials[currentIndex].image_url : defaultTestimonials[currentIndex].image} 
                      alt={testimonials.length > 0 ? testimonials[currentIndex].name : defaultTestimonials[currentIndex].name}
                      className="w-full h-full object-cover"
                    />
                  </div>
                  <div>
                    <h4 className="text-lg font-semibold text-white">
                      {testimonials.length > 0 ? testimonials[currentIndex].name : defaultTestimonials[currentIndex].name}
                    </h4>
                    <p className="text-sm text-gray-400">{testimonials.length > 0 ? testimonials[currentIndex].role : defaultTestimonials[currentIndex].role}</p>
                  </div>
                </div>
              </div>

              {/* Progress Bar */}
              <div className="absolute bottom-0 left-0 right-0 h-1 bg-white/10">
                <div 
                  className="h-full bg-gradient-to-r from-blue-500 to-purple-500 transition-all duration-500"
                  style={{ width: `${((currentIndex + 1) / (testimonials.length || defaultTestimonials.length)) * 100}%` }}
                ></div>
              </div>
            </div>

            {/* Navigation */}
            <div className="flex items-center justify-between mt-8">
              {/* Dots */}
              <div className="flex gap-2">
                {(testimonials.length > 0 ? testimonials : defaultTestimonials).map((_, index) => (
                  <button
                    key={index}
                    onClick={() => {
                      setIsAutoPlaying(false);
                      setCurrentIndex(index);
                    }}
                    className={`w-3 h-3 rounded-full transition-all duration-300 ${
                      index === currentIndex 
                        ? 'bg-blue-500 w-8' 
                        : 'bg-white/20 hover:bg-white/40'
                    }`}
                  />
                ))}
              </div>

              {/* Arrows */}
              <div className="flex gap-3">
                <button
                  onClick={prevSlide}
                  className="w-12 h-12 rounded-full glass flex items-center justify-center text-white hover:bg-white/10 transition-all"
                >
                  <ChevronLeft className="w-5 h-5" />
                </button>
                <button
                  onClick={nextSlide}
                  className="w-12 h-12 rounded-full glass flex items-center justify-center text-white hover:bg-white/10 transition-all"
                >
                  <ChevronRight className="w-5 h-5" />
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Client Logos */}
        <div className="mt-20 reveal">
          <p className="text-center text-gray-500 text-sm mb-8 uppercase tracking-wider">
            Trusted by innovative companies
          </p>
          <div className="flex flex-wrap justify-center items-center gap-8 md:gap-16 opacity-50">
            {['TechStart', 'InnovateCorp', 'EduLearn', 'FoodHub', 'DigitalPH'].map((company) => (
              <div key={company} className="text-xl font-bold text-white/40 hover:text-white/60 transition-colors cursor-default">
                {company}
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default Testimonials;
